// A hand-rolled AT Protocol OAuth client that owns every byte it sends.
//
// The point of writing this by hand rather than importing an SDK is that an SDK hides the
// wire: it retries the DPoP nonce dance for you, tolerates a missing `state`, and normalizes
// error bodies before you ever see them. Every OAuth bug this repo shipped lived in exactly
// those details, so the conformance suite needs a client that reports them literally.
//
// This is deliberately NOT a good general-purpose client. It does the minimum a spec-reading
// implementer would do, and it exposes the raw response of every leg so tests can assert on
// status codes, headers, and error strings directly.

import * as crypto from 'node:crypto';
import { exportJWK, generateKeyPair, SignJWT, type JWK, type KeyLike } from 'jose';

/** A DPoP keypair plus the RFC 7638 thumbprint the server binds tokens to. */
export interface DpopKey {
  privateKey: KeyLike;
  publicJwk: JWK;
  thumbprint: string;
}

export async function generateDpopKey(): Promise<DpopKey> {
  // `extractable` matters: exportJWK needs the public half in JWK form for the proof header.
  const { privateKey, publicKey } = await generateKeyPair('ES256', { extractable: true });
  const publicJwk = await exportJWK(publicKey);
  // RFC 7638: SHA-256 over the canonical JSON of the required members, in lexicographic
  // order. For an EC key that is exactly crv, kty, x, y — any other order or any extra
  // member yields a different thumbprint and every binding check fails.
  const canonical = JSON.stringify({
    crv: publicJwk.crv,
    kty: publicJwk.kty,
    x: publicJwk.x,
    y: publicJwk.y,
  });
  const thumbprint = crypto.createHash('sha256').update(canonical).digest('base64url');
  return { privateKey, publicJwk, thumbprint };
}

/**
 * Mint a DPoP proof (RFC 9449 §4).
 *
 * `htu` must be scheme + host + path with the query string stripped (§4.3) — a proof whose
 * htu carries `?limit=10` is rejected, which is a classic hand-rolled-client bug worth
 * being able to reproduce deliberately.
 */
export async function dpopProof(
  key: DpopKey,
  htm: string,
  url: string,
  opts: { nonce?: string; accessToken?: string; iat?: number } = {},
): Promise<string> {
  const parsed = new URL(url);
  const htu = `${parsed.origin}${parsed.pathname}`;
  const payload: Record<string, unknown> = {
    htm,
    htu,
    jti: crypto.randomUUID(),
  };
  if (opts.nonce) payload.nonce = opts.nonce;
  if (opts.accessToken) {
    // `ath` binds the proof to one access token (§4.3): base64url of SHA-256 over the token
    // string. Required at resource endpoints, absent at the token endpoint.
    payload.ath = crypto.createHash('sha256').update(opts.accessToken).digest('base64url');
  }
  return new SignJWT(payload)
    .setProtectedHeader({ typ: 'dpop+jwt', alg: 'ES256', jwk: key.publicJwk })
    .setIssuedAt(opts.iat)
    .sign(key.privateKey);
}

/** PKCE (RFC 7636 §4.1): 43–128 unreserved characters, and its S256 challenge. */
export function pkce(): { verifier: string; challenge: string } {
  const verifier = crypto.randomBytes(32).toString('base64url');
  const challenge = crypto.createHash('sha256').update(verifier).digest('base64url');
  return { verifier, challenge };
}

/** A response with its body already read, so tests can assert status, headers, and body. */
export interface WireResponse {
  status: number;
  headers: Headers;
  /** Parsed JSON when the body was JSON, else `undefined`. */
  json: any;
  text: string;
}

async function readResponse(res: Response): Promise<WireResponse> {
  const text = await res.text();
  let json: any;
  try {
    json = JSON.parse(text);
  } catch {
    json = undefined;
  }
  return { status: res.status, headers: res.headers, json, text };
}

export interface ServerMetadata {
  issuer: string;
  authorization_endpoint: string;
  token_endpoint: string;
  pushed_authorization_request_endpoint: string;
  [key: string]: unknown;
}

export async function discover(baseUrl: string): Promise<WireResponse> {
  return readResponse(await fetch(`${baseUrl}/.well-known/oauth-authorization-server`));
}

/** POST a pushed authorization request, returning the raw response. */
export async function par(
  metadata: ServerMetadata,
  params: Record<string, string>,
  opts: { dpopKey?: DpopKey } = {},
): Promise<WireResponse> {
  const headers: Record<string, string> = {
    'content-type': 'application/x-www-form-urlencoded',
  };
  if (opts.dpopKey) {
    headers.DPoP = await dpopProof(
      opts.dpopKey,
      'POST',
      metadata.pushed_authorization_request_endpoint,
    );
  }
  return readResponse(
    await fetch(metadata.pushed_authorization_request_endpoint, {
      method: 'POST',
      headers,
      body: new URLSearchParams(params).toString(),
    }),
  );
}

/**
 * POST to the token endpoint exactly once, with no nonce retry.
 *
 * The absence of a retry is the feature: a test drives the `use_dpop_nonce` challenge
 * explicitly so it can assert the challenge happened and carried a `DPoP-Nonce` header,
 * rather than having a helpful client paper over a server that never issued one.
 */
export async function tokenRequest(
  metadata: ServerMetadata,
  key: DpopKey,
  params: Record<string, string>,
  opts: { nonce?: string } = {},
): Promise<WireResponse> {
  const proof = await dpopProof(key, 'POST', metadata.token_endpoint, { nonce: opts.nonce });
  return readResponse(
    await fetch(metadata.token_endpoint, {
      method: 'POST',
      headers: {
        'content-type': 'application/x-www-form-urlencoded',
        DPoP: proof,
      },
      body: new URLSearchParams(params).toString(),
    }),
  );
}

/**
 * The nonce dance as a spec-following client performs it: try, and if the server answers
 * `use_dpop_nonce`, retry once with the nonce it handed back. Returns both legs so a test can
 * assert the challenge occurred.
 */
export async function tokenRequestWithNonceRetry(
  metadata: ServerMetadata,
  key: DpopKey,
  params: Record<string, string>,
): Promise<{ challenge?: WireResponse; final: WireResponse }> {
  const first = await tokenRequest(metadata, key, params);
  if (first.status === 400 && first.json?.error === 'use_dpop_nonce') {
    const nonce = first.headers.get('dpop-nonce');
    if (!nonce) {
      // Returning rather than throwing keeps this a *finding* the test reports, not a crash.
      return { challenge: first, final: first };
    }
    return { challenge: first, final: await tokenRequest(metadata, key, params, { nonce }) };
  }
  return { final: first };
}

/** An authenticated XRPC call with a DPoP-bound access token. */
export async function xrpc(
  baseUrl: string,
  nsid: string,
  key: DpopKey,
  accessToken: string,
  opts: { nonce?: string; scheme?: string } = {},
): Promise<WireResponse> {
  const url = `${baseUrl}/xrpc/${nsid}`;
  const proof = await dpopProof(key, 'GET', url, {
    nonce: opts.nonce,
    accessToken,
  });
  return readResponse(
    await fetch(url, {
      headers: {
        // `scheme` is overridable so a test can present a DPoP-bound token as `Bearer`
        // and assert the server refuses it.
        authorization: `${opts.scheme ?? 'DPoP'} ${accessToken}`,
        DPoP: proof,
      },
    }),
  );
}

/** Decode a JWT payload without verifying — tests assert on claims, they don't trust them. */
export function decodeJwtPayload(jwt: string): any {
  const part = jwt.split('.')[1];
  if (!part) throw new Error(`not a JWT: ${jwt.slice(0, 32)}…`);
  return JSON.parse(Buffer.from(part, 'base64url').toString('utf8'));
}

// The consent seam: drives the PDS's password consent page the way a browser would.
//
// An authorization-code flow needs a human to approve at the authorization server. Since the
// server under test is ours and its consent page is a plain password form, the suite fills
// that form directly instead of running a browser.
//
// This file is the ONLY place that knows the page's markup. Every test goes through
// `approveConsent`, so a change to the page is a one-line fix here rather than a diff across
// the whole suite — and when the markup does change, `parseConsentForm` throws a message
// naming itself, instead of failing later as a confusing "missing parameter" from the server.
//
// Rejected alternative: a test-only auto-approve endpoint. It would be immune to markup
// changes, but it would exercise a code path no real client takes — which is the exact
// failure mode (testing our own assumptions instead of the real contract) that the audit
// this suite came from was about.

/** The hidden fields the consent form round-trips, plus the scope checkboxes. */
export interface ConsentFormFields {
  hidden: Record<string, string>;
  /** One value per `granted_scope` checkbox rendered on the page. */
  grantedScopes: string[];
}

function decodeEntities(value: string): string {
  return value
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

/**
 * Extract the consent form's fields from the rendered page.
 *
 * Parses by `name=`/`value=` attribute rather than by position or surrounding markup, so
 * restyling the page does not break the suite; only renaming a field does, which is a real
 * contract change worth failing on.
 */
export function parseConsentForm(html: string): ConsentFormFields {
  const hidden: Record<string, string> = {};
  const hiddenPattern =
    /<input[^>]*type="hidden"[^>]*name="([^"]+)"[^>]*value="([^"]*)"[^>]*>/g;
  for (const match of html.matchAll(hiddenPattern)) {
    const [, name, value] = match;
    if (name !== undefined) hidden[name] = decodeEntities(value ?? '');
  }

  const grantedScopes: string[] = [];
  const checkboxPattern = /<input[^>]*name="granted_scope"[^>]*value="([^"]*)"[^>]*>/g;
  for (const match of html.matchAll(checkboxPattern)) {
    const [, value] = match;
    if (value !== undefined) grantedScopes.push(decodeEntities(value));
  }

  if (!hidden.client_id || !hidden.redirect_uri || !hidden.code_challenge) {
    throw new Error(
      'consent page markup no longer matches what tools/oauth-conformance/src/consent.ts ' +
        'expects: could not find the hidden client_id/redirect_uri/code_challenge inputs. ' +
        'If the consent page was legitimately changed, update parseConsentForm() here — ' +
        'this is the single place the suite knows the page markup.\n' +
        `Received ${html.length} bytes starting: ${html.slice(0, 200)}`,
    );
  }
  return { hidden, grantedScopes };
}

export interface ApprovalResult {
  status: number;
  /** The `Location` header of the redirect back to the client. */
  location: string;
  /** Authorization-response parameters, read from the query or the fragment. */
  params: URLSearchParams;
}

/** Read the authorization response parameters from a redirect, in either response mode. */
export function parseAuthorizationRedirect(location: string): URLSearchParams {
  const url = new URL(location);
  // A fragment-mode response puts everything after '#'; query mode uses the search string.
  return url.hash ? new URLSearchParams(url.hash.slice(1)) : url.searchParams;
}

/**
 * Approve (or deny) an authorization request as the account owner.
 *
 * `grantedScopes` defaults to every checkbox the page offered — i.e. the user approving
 * everything asked for. Passing a narrower list simulates a user unchecking permissions,
 * which is how a scope-narrowing test is written.
 */
export async function approveConsent(
  baseUrl: string,
  authorizeUrl: string,
  credentials: { identifier: string; password: string },
  opts: { decision?: 'approve' | 'deny'; grantedScopes?: string[] } = {},
): Promise<ApprovalResult> {
  const pageRes = await fetch(authorizeUrl);
  const html = await pageRes.text();
  if (pageRes.status !== 200) {
    throw new Error(
      `consent page returned ${pageRes.status} (expected 200). Body: ${html.slice(0, 400)}`,
    );
  }
  const form = parseConsentForm(html);

  const body = new URLSearchParams();
  for (const [name, value] of Object.entries(form.hidden)) body.append(name, value);
  body.append('identifier', credentials.identifier);
  body.append('password', credentials.password);
  body.append('action', opts.decision ?? 'approve');
  for (const scope of opts.grantedScopes ?? form.grantedScopes) {
    body.append('granted_scope', scope);
  }

  // `redirect: 'manual'` is essential: the authorization response *is* the redirect, and
  // following it would send the code to a callback URL that nothing is listening on.
  const res = await fetch(`${baseUrl}/oauth/authorize`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
    redirect: 'manual',
  });
  const location = res.headers.get('location');
  if (!location) {
    const text = await res.text();
    throw new Error(
      `consent POST did not redirect (status ${res.status}); the credentials may have been ` +
        `rejected. Body: ${text.slice(0, 400)}`,
    );
  }
  return { status: res.status, location, params: parseAuthorizationRedirect(location) };
}

// Per-suite fixture: a hermetic PDS plus an account that can drive the consent form.
//
// The PDS spawner, TLS proxy, mock plc.directory, and account ceremony are all reused from
// tools/mcp/test/harness.ts rather than duplicated — that module is already the second
// consumer's dependency (tools/mcp-sidecar imports it the same way), so this is an
// established seam rather than a new one.
//
// The one thing this fixture adds is the account's **password**. tools/mcp's `TestAccount`
// omits it (its suite authenticates with a session JWT), but the OAuth consent form needs a
// real credential, so provisioning is repeated here against interop's richer return value.

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

import { ADMIN_TOKEN, spawnPds, startMockPlc, type SpawnedPds } from '../../mcp/test/harness.ts';

export { ADMIN_TOKEN };

export interface ConformanceAccount {
  did: string;
  handle: string;
  email: string;
  /** The credential the consent form needs; interop sets it during the DID ceremony. */
  password: string;
}

export interface Fixture {
  baseUrl: string;
  account: ConformanceAccount;
  stop: () => void;
}

/**
 * Spawn a PDS and provision one account.
 *
 * One fixture per test *file*: interop's config module reads `EZPDS_BASE_URL` at first
 * import and caches it, so a second fixture in the same Node process would provision against
 * the first PDS. `node --test` gives each file its own process, which makes this safe as
 * long as the rule is honored.
 */
export async function startFixture(): Promise<Fixture> {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'custos-oauth-conformance-'));
  const plc = await startMockPlc();
  let pds: SpawnedPds | undefined;
  try {
    pds = await spawnPds({ dir, plcUrl: plc.url });

    process.env.EZPDS_BASE_URL = pds.baseUrl;
    process.env.EZPDS_ADMIN_TOKEN = ADMIN_TOKEN;
    process.env.EZPDS_INTEROP_STATE_DIR = path.join(dir, 'interop-state');
    process.env.EZPDS_INTEROP_PACE_MS = '25';

    const account = await import('ezpds-interop/src/account.js');
    const created = await account.createAccount({
      name: 'oauth-conformance',
      kind: 'ephemeral',
    });
    if (!created.password) {
      throw new Error(
        'interop account ceremony returned no password; the OAuth consent form cannot be ' +
          'driven without one (see tools/interop/src/account.js)',
      );
    }

    const spawned = pds;
    return {
      baseUrl: spawned.baseUrl,
      account: {
        did: created.did,
        handle: created.handle,
        email: created.email,
        password: created.password,
      },
      // Best-effort teardown: attempt every step even if an earlier one throws, because a
      // leaked pds child keeps `node --test` alive on an open handle.
      stop: () => {
        try {
          spawned.stop();
        } catch {
          /* already gone */
        }
        try {
          plc.stop();
        } catch {
          /* already gone */
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    };
  } catch (err) {
    try {
      pds?.stop();
    } catch {
      /* never started */
    }
    plc.stop();
    throw err;
  }
}

// Test runner: the PDS refuses a non-https public_url (RFC 8414), so the suite fronts it
// with a loopback TLS proxy. The proxy's self-signed cert must be trusted by every Node
// process in the test (Node reads NODE_EXTRA_CA_CERTS only at startup), hence this wrapper:
// generate the throwaway cert, then re-spawn the actual `node --test` run with it trusted.
//
// Same shape as tools/mcp/test/run.ts; the env var name is shared deliberately, because the
// harness module this suite imports reads CUSTOS_MCP_TEST_TLS_DIR.

import { spawnSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const testDir = path.dirname(fileURLToPath(import.meta.url));
const tlsDir = fs.mkdtempSync(path.join(os.tmpdir(), 'custos-oauth-conformance-tls-'));
const keyFile = path.join(tlsDir, 'key.pem');
const certFile = path.join(tlsDir, 'cert.pem');

const openssl = spawnSync(
  'openssl',
  [
    'req', '-x509', '-newkey', 'ec', '-pkeyopt', 'ec_paramgen_curve:P-256',
    '-keyout', keyFile, '-out', certFile, '-days', '7', '-nodes',
    '-subj', '/CN=custos-oauth-conformance',
    '-addext', 'subjectAltName=IP:127.0.0.1,DNS:localhost',
  ],
  { stdio: ['ignore', 'ignore', 'inherit'] },
);
if (openssl.status !== 0) {
  console.error('failed to generate the test TLS certificate (is openssl installed?)');
  process.exit(1);
}

const testFiles = fs
  .readdirSync(testDir)
  .filter((name) => name.endsWith('.test.ts'))
  .map((name) => path.join(testDir, name));

const result = spawnSync(process.execPath, ['--test', ...testFiles], {
  stdio: 'inherit',
  env: {
    ...process.env,
    NODE_EXTRA_CA_CERTS: certFile,
    CUSTOS_MCP_TEST_TLS_DIR: tlsDir,
  },
});
fs.rmSync(tlsDir, { recursive: true, force: true });
process.exit(result.status ?? 1);

